import{_ as a,o as e,c as r,a8 as o}from"./chunks/framework.0NQq3QLT.js";const _=JSON.parse('{"title":"提问的智慧","description":"","frontmatter":{},"headers":[],"relativePath":"right_question.md","filePath":"right_question.md","lastUpdated":1785592695000}'),i={name:"right_question.md"};function l(s,t,n,p,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="提问的智慧" tabindex="-1">提问的智慧 <a class="header-anchor" href="#提问的智慧" aria-label="Permalink to &quot;提问的智慧&quot;">​</a></h1><p>我强力建议您阅读<a href="http://www.catb.org/~esr/faqs/smart-questions.html" target="_blank" rel="noreferrer">提问的智慧</a>,如果您有兴趣阅读,这里还有一份<a href="https://lug.ustc.edu.cn/wiki/doc/smart-questions/" target="_blank" rel="noreferrer">简中版</a>,这是一篇很有用的文章,它讲述了如何有效提问,减少无效沟通和令人厌烦的提问方式,在生活和工作中也是很有用的,我强烈建议您阅读它。</p><h2 id="勇敢提问" tabindex="-1">勇敢提问 <a class="header-anchor" href="#勇敢提问" aria-label="Permalink to &quot;勇敢提问&quot;">​</a></h2><p>虽然一些社区存在着一些喜欢嘲笑他人的 “老资历” 但请相信任何一个社区都有乐于帮助新人的善良的同好们 您也可以加入我的qq群进行咨询</p><p>同时我也希望您真心喜欢GALGAME并且真心抱着学习的态度来提问</p><p>对于将GALGAME作为时尚单品小众标签的朋友们，我也真诚的希望您不要顶着这些标签不分场合的毫无顾忌的四处展示，这真的很影响我们的风评</p><h2 id="提问之前" tabindex="-1">提问之前 <a class="header-anchor" href="#提问之前" aria-label="Permalink to &quot;提问之前&quot;">​</a></h2><ul><li>通过互联网搜寻你遇到的问题,并在其中寻找解决方案.</li><li>如果您下载的资源出现问题,请详细阅读资源发布者写在资源页面的说明.</li><li>根据您自身的经验,做一些简单的推理尝试.</li><li>查阅本站的速查手册.</li></ul><blockquote><p>当你提出问题的时候,请先表明你已经做了上述的努力；<br> 这将有助于树立你并不是一个不劳而获且浪费别人的时间的提问者。<br> 如果你能一并表达在做了上述努力的过程中所学到的东西会更好，因为我们更乐于回答那些表现出能从答案中学习的人的问题。</p></blockquote><h2 id="如何提问" tabindex="-1">如何提问 <a class="header-anchor" href="#如何提问" aria-label="Permalink to &quot;如何提问&quot;">​</a></h2><ol><li><p><strong>确定问题</strong><br> 首先你需要简短明确的说明,你遇到了什么问题，并附上问题相关的截图和游戏文件夹的截图.</p></li><li><p><strong>问题是如何产生的</strong> 通常情况下您需要提供出现问题的游戏名,游戏版本,使用的操作系统或模拟器,并说明问题出现的节点.</p></li><li><p><strong>你做了哪些尝试</strong> 你需要说明自己做了哪些尝试<br> 而不是等到有人给出方案后告知对方自己已经进行过尝试并且无效,这是很讨厌的行为</p></li><li><p><strong>给予反馈</strong> 无论您得到的方案是否有效都应该告知提出解决方案的人,这样可以帮助对方积累更多的经验以更有效的帮助大家解决问题.</p></li></ol>',11)])])}const u=a(i,[["render",l]]);export{_ as __pageData,u as default};
